import java.util.*;
import java.io.*;

public class Prac {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int size = input.nextInt();
        int limit = input.nextInt();
        int[] data = new int[size];
        for (int index = 0; index < size; index++) {
            data[index] = input.nextInt();
        }
        int countSegments = 0;
        int startIdx = 0;
        int evenCount = 0, oddCount = 0;
        List<Integer> segmentDifferences = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            if (data[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            if (evenCount == oddCount && i != size - 1) {
                int diff = Math.abs(data[i + 1] - data[startIdx]);
                segmentDifferences.add(diff);
                startIdx = i + 1;
                evenCount = 0;
                oddCount = 0;
            }
        }
        if (segmentDifferences.size() > 0) {
            Collections.sort(segmentDifferences);
            int totalDiff = 0;
            for (int i = 0; i < segmentDifferences.size(); i++) {
                totalDiff += segmentDifferences.get(i);
                if (totalDiff > limit) {
                    countSegments = i;
                    break;
                } else {
                    countSegments = i + 1;
                }
            }
        } else {
            if (size > 0) {
                int diff = Math.abs(data[0] - data[0]);
                if (diff >= limit) {
                    countSegments = 1;
                }
            }
        }
        System.out.println(countSegments);
    }
}
